<script>var adminMenuButton=document.getElementById('sbToggle');if(adminMenuButton){adminMenuButton.setAttribute('aria-expanded','false');adminMenuButton.setAttribute('aria-controls','adminSidebar')}document.addEventListener('keydown',function(event){if(event.key==='Escape'){document.body.classList.remove('mobile-open');if(adminMenuButton)adminMenuButton.setAttribute('aria-expanded','false')}});</script><script>(function(){const body=document.body,key='admin_sb_collapsed';if(localStorage.getItem(key)==='1')body.classList.add('sidebar-collapsed');const btn=document.getElementById('sbToggle');if(btn)btn.addEventListener('click',()=>{if(window.matchMedia('(max-width: 767px)').matches){const isOpen=body.classList.toggle('mobile-open');btn.setAttribute('aria-expanded',String(isOpen))}else{body.classList.toggle('sidebar-collapsed');localStorage.setItem(key,body.classList.contains('sidebar-collapsed')?'1':'0')}});document.querySelectorAll('[data-close-menu]').forEach(el=>el.addEventListener('click',()=>{body.classList.remove('mobile-open');if(btn)btn.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-close-menu]').forEach(el=>el.addEventListener('keydown',event=>{if(event.key==='Escape'){body.classList.remove('mobile-open');if(btn)btn.setAttribute('aria-expanded','false')}}));function tick(){document.querySelectorAll('.js-clock').forEach(el=>{try{el.textContent=new Intl.DateTimeFormat('en-PH', {dateStyle:'medium',timeStyle:'medium',timeZone:el.dataset.tz||'Asia/Manila'}).format(new Date())}catch(e){el.textContent=new Date().toLocaleString()}})}tick();setInterval(tick,1000);window.addEventListener('load',()=>document.body.classList.remove('opacity-0','translate-y-1'))})();</script></body></html>
